private theorem one_le_scale
    {B : ℕ} {sigma kappa c0 : ℝ} {d : MediumAtom}
    (hd : MediumAdmissible B sigma kappa c0 d) : 1 ≤ d.scale

theorem mediumAdmissible_residue_ne_zero
    {B : ℕ} {sigma kappa c0 : ℝ} {d : MediumAtom}
    (hc0 : 0 < c0) (hd : MediumAdmissible B sigma kappa c0 d) : d.residue ≠ 0

private theorem card_alphaCarrier_le
    {B : ℕ} {sigma kappa c0 : ℝ} {d : MediumAtom}
    (hd : MediumAdmissible B sigma kappa c0 d) : (d.alphaCarrier.card : ℝ) ≤ 2 * d.U

private theorem gamma_norm_le_one
    {B : ℕ} {sigma kappa c0 : ℝ} {d : MediumAtom}
    (hd : MediumAdmissible B sigma kappa c0 d) {r : ℕ × ℕ × ℕ}
    (hr : r ∈ d.complexFactorLabels) : ‖d.complexFactorGamma r‖ ≤ 1

private theorem eventually_const_rpow_le_logBudget (C A : ℝ) (hC : 0 ≤ C)
    {delta : ℝ} (hdelta : 0 < delta) :
    ∀ᶠ x : ℝ in atTop, C * x ^ (1 - delta) ≤ x / (Real.log x) ^ A
